cd multicode/obelisk/full; python3 - <<'E'
p='core/archaeology.mjs'
s=open(p).read()
new='''  // statSummary: по spec arch правилам 16–21 (таблицы statCells / statTerms, порядок double как в правиле 18)
  const statCells = table(T.statCells);
  const statTerms = table(T.statTerms);
  const termsOf = new Map();
  for (const r of statTerms) {
    if (!termsOf.has(r.cell)) termsOf.set(r.cell, []);
    termsOf.get(r.cell).push(r);
  }

  function statSummary(input) {
    const { alloc, upgrades: upg, ext } = input;
    const boosted = (k, lvl, flag) => (flag ? (lvl >= 1 ? k : 0) : k * lvl);
    const value = (r) => {
      switch (r.src) {
        case 'const': return r.k;
        case 'alloc': {
          let c = r.k;
          if (r.boost != null) c += boosted(r.boostK, upg[r.boost], r.boostFlag);
          if (r.boost2 != null) c += boosted(r.boost2K, upg[r.boost2], r.boost2Flag);
          return c * alloc[r.i];
        }
        case 'upg': return r.k * upg[r.i];
        case 'ext':
          if (r.when === 'linear') return r.k * ext[r.i];
          if (r.when === 'eq1') return ext[r.i] === 1 ? r.k : 0;
          return ext[r.i] !== 0 ? r.k : 0;
        case 'enrage': return input.enrageStacks > 0 ? (r.k + r.per * upg[r.i]) / r.div : 0;
        default: throw new Error(`statSummary: источник ${r.src}`);
      }
    };
    const factor = (r) => {
      switch (r.src) {
        case 'ext': return ext[r.i] !== 0 ? r.k : 1;
        case 'upgFlag': return upg[r.i] >= 1 ? r.k : 1;
        case 'speedStacks': return input.speedStacks > 0 ? r.k : 1;
        case 'duration': return input.durations[r.i] > 0 ? r.k : 1;
        case 'highStage': return ext[r.i] === r.k ? 1 + r.per * Math.min(input.highestStage, r.cap) : 1;
        default: throw new Error(`statSummary: множитель ${r.src}`);
      }
    };
    return statCells.map((c) => {
      if (c.kind === 'copy') return input[c.from];
      if (c.kind === 'const') return c.value;
      const rows = termsOf.get(c.cell);
      let v = 0.0;
      for (let j = 0; j < rows.length; j++) {
        const r = rows[j];
        if (r.part !== 'flat') continue;
        if (r.sum === 0) { v += value(r); continue; }
        let s = 0.0;
        while (j < rows.length && rows[j].part === 'flat' && rows[j].sum === r.sum) { s += value(rows[j]); j++; }
        j--;
        v += s;
      }
      const groups = [...new Set(rows.filter((r) => r.part === 'pct').map((r) => r.group))].sort((a, b) => a - b);
      for (const g of groups) {
        let p = 0.0;
        for (const r of rows) if (r.part === 'pct' && r.group === g) p += value(r);
        v *= p;
      }
      for (const r of rows) if (r.part === 'mult') v *= factor(r);
      return c.round ? Math.floor(v + 0.5) : v;
    });
  }

  return { instaCooldown: C['ability.instaCooldown'], xpForLevel, generateField, blockDeath, abilityLimits, cardEffects, activate, tick, statSummary };
'''
old="  return { instaCooldown: C['ability.instaCooldown'], xpForLevel, generateField, blockDeath, abilityLimits, cardEffects, activate, tick };\n"
assert old in s
open(p,'w').write(s.replace(old,new))
E
